add_action( 'wp_footer', 'perfectpixel_floating_social_icons' );

function perfectpixel_floating_social_icons() {
	$links = array(
		'Facebook'  => array( 'f', '{{social_facebook_url}}' ),
		'Instagram' => array( 'IG', '{{social_instagram_url}}' ),
		'LinkedIn'  => array( 'in', '{{social_linkedin_url}}' ),
		'X'         => array( 'X', '{{social_x_url}}' ),
		'YouTube'   => array( 'YT', '{{social_youtube_url}}' ),
		'TikTok'    => array( 'TT', '{{social_tiktok_url}}' ),
	);
	$items = '';
	foreach ( $links as $name => $link ) {
		$url = trim( $link[1] );
		if ( $url ) {
			$items .= '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener" aria-label="' . esc_attr( $name ) . '" title="' . esc_attr( $name ) . '">' . esc_html( $link[0] ) . '</a>';
		}
	}
	if ( '' === $items ) {
		return;
	}
	$color = sanitize_hex_color( '{{social_buttons_color}}' );
	echo '<style>.perfectpixel-social-float{position:fixed;left:0;top:50%;transform:translateY(-50%);z-index:9998;display:flex;flex-direction:column}.perfectpixel-social-float a{display:block;width:42px;height:42px;line-height:42px;text-align:center;font:600 14px/42px sans-serif;color:#fff;background:' . esc_attr( $color ? $color : '#1d2327' ) . ';text-decoration:none;border-bottom:1px solid rgba(255,255,255,.2);transition:width .15s}.perfectpixel-social-float a:hover,.perfectpixel-social-float a:focus{width:50px}@media (max-width:767px){.perfectpixel-social-float{display:none}}</style>';
	echo '<nav class="perfectpixel-social-float" aria-label="Social media">' . $items . '</nav>';
}
